  function showPage(page){if((["team","stats","projects","announcements","webhooks"].includes(page))&&currentProfile?.role!=="admin")page="dashboard";["dashboard","compose","reports","tasks","presence","messages","stats","team","projects","announcements","webhooks"].forEach(p=>$(p+"Page").classList.toggle("hidden",p!==page));const section=pageSections[page]||"home";document.querySelectorAll("#mainNav [data-section]").forEach(button=>button.classList.toggle("active",button.dataset.section===section));const subNav=$("subNav"),pages=(sectionPages[section]||[]).filter(item=>!item.admin||currentProfile?.role==="admin");subNav.innerHTML=pages.map(item=>`<button type="button" class="${item.id===page?"active":""}" data-sub-page="${item.id}">${item.id==="team"?"Gestion équipe":item.label}</button>`).join("");subNav.classList.toggle("hidden",pages.length<2);subNav.querySelectorAll("[data-sub-page]").forEach(button=>button.onclick=()=>showPage(button.dataset.subPage));if(currentUser)localStorage.setItem("devreports-page-"+currentUser.id,page);history.replaceState(null,"",location.pathname+location.search+"#"+page);if(page==="compose")$("project").focus();if(page==="reports")renderReports();if(page==="tasks")loadTasks();if(page==="presence")loadPresencePage();if(page==="messages"){loadMessages();connectTeamMessages()}else disconnectTeamMessages();if(page==="stats")renderStats();if(page==="team"&&allProfiles.length)renderTeam();if(page==="projects")loadProjects();if(page==="announcements"||page==="dashboard")loadAnnouncements();if(page==="webhooks")loadWebhookSettings();}
