  async function refreshNotifications(announce=false){if(!db||!currentUser)return;const [{data,error},unreadDirect]=await Promise.all([db.from("team_notifications").select("id,user_id,actor_id,kind,title,body,target_page,target_id,created_at,read_at").order("created_at",{ascending:false}).limit(50),db.from("team_notifications").select("actor_id").eq("kind","direct_message").is("read_at",null).limit(1000)]);if(error){$("notificationHomeList").innerHTML='<div class="empty">Notifications indisponibles. Vérifie que la migration SQL des notifications est appliquée.</div>';$("notificationsList").innerHTML='<div class="empty">Vérifie la configuration des notifications Supabase.</div>';return}teamNotifications=data||[];directUnreadCounts=new Map();for(const row of unreadDirect.data||[])if(row.actor_id)directUnreadCounts.set(row.actor_id,(directUnreadCounts.get(row.actor_id)||0)+1);const latest=teamNotifications[0];if(announce&&latest&&latest.id!==lastNotificationId&&!latest.read_at)toast(`${latest.title}${latest.body?": "+latest.body.slice(0,80):""}`);lastNotificationId=latest?.id||lastNotificationId;renderNotifications()}
