  function printReport(id){const r=allReports.find(item=>item.id===id);if(!r)return toast("Rapport introuvable.",true);const moderation=r.report_type==="moderation"?'<section class="pdf-section"><h2>Intervention de modération</h2><div class="pdf-grid"><div><small>Plateforme</small><b>'+escapeHtml(r.platform||"—")+'</b></div><div><small>Action</small><b>'+escapeHtml(r.moderation_action||"—")+'</b></div><div><small>Membre concerné</small><b>'+escapeHtml(r.moderated_user||"—")+'</b></div></div></section>':"";const discord=r.report_type==="discord_management"?'<section class="pdf-section"><h2>Gestion du serveur Discord</h2><div class="pdf-grid"><div><small>Serveur</small><b>'+escapeHtml(r.discord_server||"—")+'</b></div><div><small>Élément géré</small><b>'+escapeHtml(r.discord_area||"—")+'</b></div><div><small>Salon / rôle</small><b>'+escapeHtml(r.discord_target||"—")+'</b></div></div><p style="margin-top:10px">'+escapeHtml(r.discord_changes||"Aucun détail renseigné.")+'</p></section>':"";const badge=r.report_type==="moderation"?"MODÉRATION":r.report_type==="discord_management"?"GESTION DISCORD":"RAPPORT DE TRAVAIL";$('pdfPrintRoot').innerHTML='<article class="pdf-sheet"><header class="pdf-brand"><div class="pdf-mark">D</div><div><b>DevReports</b><small>Compte rendu d’équipe</small></div><span class="pdf-status">'+badge+'</span></header><div class="pdf-kicker">'+escapeHtml(r.project||"Projet")+' · '+escapeHtml(r.category||"")+'</div><h1>'+escapeHtml(r.title||"Rapport")+'</h1><div class="pdf-byline"><span>Rédigé par <b>'+escapeHtml(r.profiles?.display_name||"Membre")+'</b></span><span>'+dateLabel(r.created_at)+'</span></div><div class="pdf-summary"><div><small>Projet</small><b>'+escapeHtml(r.project||"—")+'</b></div><div><small>Version / build</small><b>'+escapeHtml(r.version||"Non précisée")+'</b></div><div><small>Catégorie</small><b>'+escapeHtml(r.category||"—")+'</b></div></div>'+moderation+discord+'<section class="pdf-section"><h2>Travaux réalisés</h2><p>'+escapeHtml(r.work||"—")+'</p></section><div class="pdf-two-col"><section class="pdf-section"><h2>Problèmes rencontrés</h2><p>'+escapeHtml(r.issues||"Aucun problème signalé.")+'</p></section><section class="pdf-section"><h2>Prochaines étapes</h2><p>'+escapeHtml(r.next_steps||"Aucune étape renseignée.")+'</p></section></div><section class="pdf-section pdf-tags"><div><small>Rôles concernés</small><p>'+escapeHtml(roleLabels(r.author_roles))+'</p></div><div><small>Types d’actions</small><p>'+escapeHtml((r.action_types||[]).join(" · ")||"Non précisés")+'</p></div></section><footer class="pdf-footer"><span>DevReports · Document généré depuis l’espace équipe</span><span>'+escapeHtml(r.profiles?.display_name||"Membre")+'</span></footer></article>';document.body.classList.add("printing-report");requestAnimationFrame(()=>requestAnimationFrame(()=>window.print()));const cleanup=()=>{document.body.classList.remove("printing-report");$("pdfPrintRoot").innerHTML="";window.removeEventListener("afterprint",cleanup)};window.addEventListener("afterprint",cleanup);setTimeout(cleanup,60000)}
  async function renderStats(){if(currentProfile?.role!=="admin")return;$('statPeople').textContent=String(allProfiles.filter(p=>p.status==="active").length);const draw=(id,rows)=>{const target=$(id);if(!target)return;const max=Math.max(1,...rows.map(x=>x.n));target.innerHTML=rows.length?rows.map(x=>`<div class="barrow"><span>${escapeHtml(x.name)}</span><div class="bar"><i style="width:${Math.max(3,x.n/max*100)}%"></i></div><b>${x.n}</b></div>`).join(""):'<div class="empty">Aucune donnée active.</div>'};const counts=new Map();for(const report of allReports)counts.set(report.user_id,(counts.get(report.user_id)||0)+1);const byPerson=allProfiles.filter(p=>!p.status||p.status==="active").map(p=>({name:p.nickname||p.display_name,n:counts.get(p.id)||0})).sort((a,b)=>b.n-a.n);draw("peopleStats",byPerson);const cats={};allReports.forEach(r=>cats[r.category]=(cats[r.category]||0)+1);draw("categoryStats",Object.entries(cats).map(([name,n])=>({name,n})));draw("dashboardStats",byPerson.slice(0,5));try{const [warnings,absences,lates]=await Promise.all([fetchAllRows("member_warnings","id,member_id,created_at"),fetchAllRows("team_absences","id,user_id,status,end_date,absence_kind"),fetchAllRows("late_notices","id,user_id,status,late_kind")]);const activeWarnings=warnings||[],today=new Date().toISOString().slice(0,10),activeAbsences=(absences||[]).filter(row=>["pending","approved","recorded"].includes(row.status)&&row.end_date>=today),activeLates=(lates||[]).filter(row=>["pending","acknowledged"].includes(row.status)),activeSanctions=allProfiles.filter(profile=>profile.status==="banned"||(profile.status==="suspended"&&(!profile.suspended_until||new Date(profile.suspended_until).getTime()>Date.now()))).map(profile=>({member_id:profile.id}));$('activeWarningsStat').textContent=String(activeWarnings.length);$('activeSanctionsStat').textContent=String(activeSanctions.length);$('activeAbsencesStat').textContent=String(activeAbsences.length);$('activeLatesStat').textContent=String(activeLates.length);const names=new Map(allProfiles.map(profile=>[profile.id,profile.nickname||profile.display_name||'Membre'])),group=(rows,key)=>{const map=new Map();rows.forEach(row=>map.set(row[key],(map.get(row[key])||0)+1));return [...map].map(([id,n])=>({name:names.get(id)||'Membre',n})).sort((a,b)=>b.n-a.n)};draw('warningsByMemberStats',group(activeWarnings,'member_id'));draw('sanctionsByMemberStats',group(activeSanctions,'member_id'));draw('absencesByMemberStats',group(activeAbsences,'user_id'));draw('latesByMemberStats',group(activeLates,'user_id'))}catch(error){console.warn('Statistiques équipe incomplètes',error);['warningsByMemberStats','sanctionsByMemberStats','absencesByMemberStats','latesByMemberStats'].forEach(id=>{const target=$(id);if(target)target.innerHTML='<div class="empty">Statistiques indisponibles. Vérifie les droits de lecture Supabase.</div>'})}}
