  function openPasswordRecoveryDialog(){const dialog=$("passwordRecoveryDialog");dialog.innerHTML='<form id="passwordRecoveryForm" class="dialog-content"><div class="dialog-icon">↻</div><h2 id="passwordRecoveryTitle">Choisis un nouveau mot de passe</h2><p>Le lien est vérifié. Saisis un mot de passe d’au moins 8 caractères pour terminer la réinitialisation.</p><label for="recoveryPassword">Nouveau mot de passe</label><input id="recoveryPassword" type="password" minlength="8" autocomplete="new-password" required><label for="recoveryPasswordConfirm">Confirmer le mot de passe</label><input id="recoveryPasswordConfirm" type="password" minlength="8" autocomplete="new-password" required><div class="dialog-actions"><button class="btn" type="submit">Mettre à jour</button></div></form>';dialog.querySelector("form").onsubmit=async event=>{event.preventDefault();const password=$("recoveryPassword").value;if(password.length<8)return toast("Utilise au moins 8 caractères.",true);if(password!==$("recoveryPasswordConfirm").value)return toast("Les deux mots de passe ne correspondent pas.",true);const submit=event.submitter;submit.disabled=true;const {error}=await db.auth.updateUser({password});submit.disabled=false;if(error)return toast("Modification impossible : "+error.message,true);toast("Mot de passe modifié. Tu peux maintenant te connecter.");await db.auth.signOut();dialog.close();passwordRecoveryActive=false;setView(false)};dialog.showModal();$("recoveryPassword").focus()}
  async function createTeamRole(){const label=$("newRoleName").value.trim();if(label.length<2||label.length>50)return toast("Le nom du rôle doit contenir entre 2 et 50 caractères.",true);const roleKey=label.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"_").replace(/^_+|_+$/g,"").slice(0,40);if(!/^[a-z][a-z0-9_]{1,39}$/.test(roleKey))return toast("Choisis un nom de rôle plus précis.",true);const {error}=await db.from("team_roles").insert({role_key:roleKey,label});if(error)return toast("Création impossible : "+error.message,true);$("newRoleName").value="";toast("Rôle créé.");await refreshReports()}
