  async function loadTaskComments(taskId){const container=$("taskCommentsList");if(!container)return;const {data,error}=await db.from("task_comments").select("id,user_id,body,created_at").eq("task_id",taskId).order("created_at",{ascending:true});if(error){container.innerHTML='<p class="muted">Commentaires indisponibles. Vérifie la migration SQL.</p>';return}const comments=data||[];container.innerHTML=comments.map(comment=>`<article class="task-comment"><header class="task-comment-head"><span><strong>${escapeHtml(allProfiles.find(p=>p.id===comment.user_id)?.display_name||(comment.user_id===currentUser.id?currentProfile.display_name:"Membre"))}</strong> · ${dateLabel(comment.created_at)}</span>${comment.user_id===currentUser.id||currentProfile.role==="admin"?`<button class="task-comment-delete" data-delete-comment="${comment.id}">Supprimer</button>`:""}</header><p>${escapeHtml(comment.body)}</p></article>`).join("")||'<p class="muted">Pas encore de commentaire. Lance la discussion.</p>';container.querySelectorAll("[data-delete-comment]").forEach(button=>button.onclick=async()=>{const {error}=await db.from("task_comments").delete().eq("id",button.dataset.deleteComment);if(error)return toast(error.message,true);loadTaskComments(taskId)})}
