  async function downloadBackup(){const button=$("backupBtn");if(!await siteDialog({title:"Télécharger un export des données ?",message:"Le fichier peut contenir des rapports internes et des informations sur l’équipe. Conserve-le dans un emplacement privé.",confirmText:"Télécharger"}))return;button.disabled=true;const oldText=button.textContent;button.textContent="Préparation…";try{const tables=["profiles","reports","projects","team_roles","member_warnings","warning_disputes","report_disputes","member_sanctions","sanction_disputes","team_absences","late_notices","team_messages","team_announcements","tasks","task_comments"],contents={};for(const table of tables)contents[table]=await fetchAllRows(table);const snapshot={format:"devreports-data-export",version:2,generated_at:new Date().toISOString(),project:SUPABASE_URL.replace(/^https:\/\//,""),contents};const blob=new Blob([JSON.stringify(snapshot,null,2)],{type:"application/json;charset=utf-8"}),url=URL.createObjectURL(blob),link=document.createElement("a"),stamp=new Date().toISOString().replace(/[:.]/g,"-");link.href=url;link.download="devreports-export-"+stamp+".json";document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Export JSON téléchargé. Garde-le en lieu sûr.")}catch(error){console.error(error);toast("Export impossible : "+(error.message||"erreur Supabase"),true)}finally{button.disabled=false;button.textContent=oldText}}
