  function warningCard(w,memberName,authorName,canManage=false,index=0,contestStatus=null){const motif=w.motif||"Autre",description=w.description||w.reason||"Aucune description.";const memberAction=contestStatus?`<span class="pill">${contestStatus==="open"?"Contestation envoyée":contestStatus==="reviewed"?"Contestation examinée":"Contestation classée"}</span>`:`<button class="btn secondary" data-contest-warning="${w.id}">Contester ce warn</button>`;return `<article class="warning-card" style="animation-delay:${Math.min(index*55,330)}ms"><div class="warning-card-head"><div class="warning-card-title"><span class="warning-symbol" aria-hidden="true">!</span><div><h3>${escapeHtml(motif)}</h3><span class="warning-motif">${escapeHtml(memberName)}</span></div></div><span class="warning-date">${dateLabel(w.created_at)}</span></div><div class="warning-description">${escapeHtml(description)}</div><div class="warning-meta"><span>Émis par <strong>${escapeHtml(authorName||"Administration")}</strong></span><span>${dateLabel(w.created_at)}</span></div>${canManage?`<div class="warning-actions"><button class="btn secondary" data-edit-warning="${w.id}">Modifier</button><button class="btn danger" data-delete-warning="${w.id}">Supprimer</button></div>`:`<div class="warning-actions">${memberAction}</div>`}</article>`}
