  function announcementRecipientName(id){const profile=allProfiles.find(item=>item.id===id);return profile?.nickname||profile?.display_name||'Membre'}
  function announcementCard(row,admin=false){return `<article class="announcement-card ${admin?'announcement-admin-card':'announcement-featured-card'}">${admin?'':'<div class="announcement-featured-mark" aria-hidden="true">✦</div>'}<div class="announcement-card-meta"><span class="announcement-tag">${row.recipient_id?`Pour ${escapeHtml(announcementRecipientName(row.recipient_id))}`:'Toute l’équipe'}</span><time>${dateLabel(row.created_at)}</time></div><h3>${escapeHtml(row.title)}</h3><p>${escapeHtml(row.body)}</p>${admin?`<div class="announcement-card-meta"><span>${[row.display_home?'Accueil':'',row.display_banner?'Bandeau':''].filter(Boolean).join(' · ')||'Aucun emplacement'}${row.active?'':' · Inactive'}${row.ends_at?' · Jusqu’au '+dateLabel(row.ends_at):''}</span><div class="presence-actions"><button class="btn secondary" data-edit-announcement="${row.id}">Modifier</button><button class="btn danger" data-delete-announcement="${row.id}">Supprimer</button></div></div>`:''}</article>`}
  async function loadAnnouncements(){if(!currentUser||!db)return;const admin=currentProfile?.role==='admin';let query=db.from('team_announcements').select('id,title,body,recipient_id,display_home,display_banner,active,starts_at,ends_at,created_by,created_at');if(!admin)query=query.eq('active',true);const {data,error}=await query.order('created_at',{ascending:false}).limit(100);if(error){console.warn('Annonces indisponibles',error);$('announcementHome').classList.add('hidden');$('announcementBanner').classList.add('hidden');if(admin&&$('announcementList'))$('announcementList').innerHTML='<div class="empty">Annonces indisponibles. Applique la dernière version de supabase_setup.sql.</div>';return}const now=Date.now(),rows=(data||[]).filter(row=>new Date(row.starts_at).getTime()<=now&&(!row.ends_at||new Date(row.ends_at).getTime()>now));const home=rows.filter(row=>row.display_home),banner=rows.filter(row=>row.display_banner);$('announcementHomeList').innerHTML=home.map(row=>announcementCard(row)).join('');$('announcementHome').classList.toggle('hidden',home.length===0||$('dashboardPage').classList.contains('hidden'));$('announcementBanner').innerHTML=banner.map(row=>`<article class="announcement-banner-item"><span class="announcement-icon">✦</span><div><strong>${escapeHtml(row.title)}</strong><p>${escapeHtml(row.body)}</p></div></article>`).join('');$('announcementBanner').classList.toggle('hidden',banner.length===0);if(!admin||!$('announcementList'))return;const recipient=$('announceRecipient'),selected=recipient.value;recipient.innerHTML='<option value="">Toute l’équipe</option>'+allProfiles.map(p=>`<option value="${escapeHtml(p.id)}">${escapeHtml(p.nickname||p.display_name)}${p.status==='active'?'':' · inactif'}</option>`).join('');recipient.value=selected;$('announcementList').innerHTML=(data||[]).map(row=>announcementCard(row,true)).join('')||'<div class="empty">Aucune annonce pour le moment.</div>';document.querySelectorAll('[data-edit-announcement]').forEach(button=>button.onclick=()=>editAnnouncement((data||[]).find(row=>row.id===button.dataset.editAnnouncement)));document.querySelectorAll('[data-delete-announcement]').forEach(button=>button.onclick=async()=>{if(!await siteDialog({title:'Supprimer cette annonce ?',message:'Le message sera retiré pour tous ses destinataires.',confirmText:'Supprimer',danger:true}))return;const {error}=await db.from('team_announcements').delete().eq('id',button.dataset.deleteAnnouncement);if(error)return toast('Suppression impossible : '+error.message,true);toast('Annonce supprimée.');loadAnnouncements()})}
  function editAnnouncement(row){if(!row)return;editingAnnouncementId=row.id;$('announcementFormHeading').textContent='Modifier l’annonce';$('announcementTitle').value=row.title;$('announcementBody').value=row.body;$('announceRecipient').value=row.recipient_id||'';$('announcementShowHome').checked=row.display_home;$('announcementShowBanner').checked=row.display_banner;$('announcementEndsAt').value=row.ends_at?localDateTimeInputValue(new Date(row.ends_at)):'';$('announcementSubmit').textContent='Enregistrer les modifications';$('announcementCancelEdit').classList.remove('hidden');$('announcementForm').scrollIntoView({behavior:'smooth',block:'center'})}
  function resetAnnouncementForm(){editingAnnouncementId=null;$('announcementForm').reset();$('announcementShowHome').checked=true;$('announcementFormHeading').textContent='Nouvelle annonce';$('announcementSubmit').textContent='Publier l’annonce';$('announcementCancelEdit').classList.add('hidden')}
  $('announcementCancelEdit').onclick=resetAnnouncementForm;
  $('announcementForm').onsubmit=async event=>{event.preventDefault();if(currentProfile?.role!=='admin')return;const title=$('announcementTitle').value.trim(),body=$('announcementBody').value.trim(),display_home=$('announcementShowHome').checked,display_banner=$('announcementShowBanner').checked,endsValue=$('announcementEndsAt').value;if(title.length<2||body.length<2)return toast('Renseigne un titre et un message.',true);if(!display_home&&!display_banner)return toast('Choisis au moins un emplacement.',true);if(endsValue&&new Date(endsValue).getTime()<=Date.now())return toast('La date d’expiration doit être dans le futur.',true);const payload={title,body,recipient_id:$('announceRecipient').value||null,display_home,display_banner,active:true,ends_at:endsValue?new Date(endsValue).toISOString():null};const wasEditing=!!editingAnnouncementId,result=wasEditing?await db.from('team_announcements').update(payload).eq('id',editingAnnouncementId):await db.from('team_announcements').insert({...payload,created_by:currentUser.id}).select('id');if(result.error)return toast('Enregistrement impossible : '+result.error.message,true);resetAnnouncementForm();if(!wasEditing&&result.data?.[0]?.id)notifyWebhook('announcement_published',result.data[0].id);toast(wasEditing?'Annonce modifiée.':'Annonce publiée.');loadAnnouncements()};
  const webhookEvents=['report_created','absence_requested','late_reported','absence_recorded','late_recorded','warning_created','sanction_created','announcement_published'];
  const webhookEventLabels={report_created:'Rapports publiés',absence_requested:'Demandes d’absence',late_reported:'Retards signalés',absence_recorded:'Absences consignées',late_recorded:'Retards consignés',warning_created:'Avertissements',sanction_created:'Suspensions / bannissements',announcement_published:'Annonces'};
  let webhookConfigs=[],editingWebhookId=null;
  async function callWebhook(action,extra={}){let {data:sessionData,error:sessionError}=await db.auth.getSession();if(sessionError)throw new Error('Impossible de vérifier la session. Déconnecte-toi puis reconnecte-toi.');let session=sessionData.session;if(!session)throw new Error('Ta session a expiré. Déconnecte-toi puis reconnecte-toi avant de gérer le webhook.');const refresh=async()=>{const refreshed=await db.auth.refreshSession();if(refreshed.error||!refreshed.data.session)throw new Error('Ta session a expiré. Déconnecte-toi puis reconnecte-toi avant de gérer le webhook.');session=refreshed.data.session};if(!session.expires_at||session.expires_at*1000<Date.now()+60000)await refresh();const invoke=()=>db.functions.invoke('manage-team-webhook',{body:{action,...extra},headers:{Authorization:`Bearer ${session.access_token}`}});const getErrorMessage=async result=>{if(!result.error&&!result.data?.error)return '';let message=result.data?.error;if(!message&&result.error?.context&&typeof result.error.context.clone==='function'){try{message=(await result.error.context.clone().json())?.error}catch{}}return message||result.error?.message||'La fonction webhook a échoué.'};let result=await invoke(),message=await getErrorMessage(result);if(message.includes('Session invalide')||message.includes('Session invalide ou expirée')){await refresh();result=await invoke();message=await getErrorMessage(result)}if(result.error||result.data?.error)throw new Error(message||'Vérifie la configuration du webhook et les journaux Supabase.');return result.data}
  async function notifyWebhook(eventType,recordId){if(!recordId)return;try{const result=await callWebhook('notify',{eventType,recordId});if(result.failed?.length)toast(`Événement enregistré, mais ${result.failed.length} webhook(s) n’ont pas pu recevoir la notification.`,true)}catch(error){console.warn('Notification Discord non envoyée',error.message);toast('Enregistrement effectué, mais la notification Discord a échoué. Vérifie les webhooks.',true)}}
  function resetWebhookEditor(){editingWebhookId=null;$('webhookForm').reset();$('webhookUsernameMode').value='named';$('webhookAvatarPreview').removeAttribute('src');$('webhookAvatarPreview').classList.add('hidden');$('webhookFormHeading').textContent='Ajouter un webhook';$('webhookSave').textContent='Ajouter le webhook';$('webhookUrlHint').textContent='Requise pour créer un nouveau webhook.';$('webhookCancelEdit').classList.add('hidden')}
  function renderWebhookList(){const list=$('webhookList');$('webhookCount').textContent=String(webhookConfigs.length);$('webhookStatus').textContent=webhookConfigs.length?`${webhookConfigs.length} actif${webhookConfigs.length>1?'s':''}`:'Aucun webhook';$('webhookStatus').classList.toggle('webhook-active',webhookConfigs.length>0);list.innerHTML=webhookConfigs.map(config=>`<article class="webhook-card"><div class="webhook-card-heading"><div>${config.avatar_url?`<img class="webhook-card-avatar" src="${escapeHtml(config.avatar_url)}" alt="" loading="lazy">`:'<span class="webhook-live-dot"></span>'}<h4>${escapeHtml(config.name)}</h4></div><span class="pill">${config.username_mode==='brand'?'DevReports':`${escapeHtml(config.name)} | DevReports`}</span></div><p class="webhook-card-label">Événements reçus</p><div class="webhook-tags">${(config.events||[]).map(event=>`<span>${escapeHtml(webhookEventLabels[event]||event)}</span>`).join('')||'<span>Aucun événement</span>'}</div><div class="actions webhook-card-actions"><button class="btn secondary" type="button" data-edit-webhook="${escapeHtml(config.id)}">Modifier</button><button class="btn secondary" type="button" data-test-webhook="${escapeHtml(config.id)}">Tester</button><button class="btn danger" type="button" data-delete-webhook="${escapeHtml(config.id)}">Supprimer</button></div></article>`).join('')||'<div class="empty">Aucun webhook configuré. Ajoute une destination Discord à droite.</div>';list.querySelectorAll('[data-edit-webhook]').forEach(button=>button.onclick=()=>{const config=webhookConfigs.find(item=>item.id===button.dataset.editWebhook);if(!config)return;editingWebhookId=config.id;$('webhookFormHeading').textContent=`Modifier ${config.name}`;$('webhookSave').textContent='Enregistrer les modifications';$('webhookUrlHint').textContent='Laisse vide pour garder l’URL actuelle. Le lien ne sera pas réaffiché.';$('webhookName').value=config.name;$('webhookUsernameMode').value=config.username_mode||'named';$('webhookAvatarUrl').value=config.avatar_url||'';updateWebhookAvatarPreview();$('webhookMentionTarget').value=config.mention_target||'';$('webhookEmbedImage').value=config.embed_image_url||'';$('webhookMessageTemplate').value=config.message_template||'';fillExtraWebhookEmbeds(config.extra_embeds||[]);$('webhookUrl').value='';document.querySelectorAll('#webhookForm input[type=checkbox]').forEach(input=>input.checked=(config.events||[]).includes(input.value));$('webhookCancelEdit').classList.remove('hidden');$('webhookForm').scrollIntoView({behavior:'smooth',block:'center'})});list.querySelectorAll('[data-test-webhook]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await callWebhook('test',{webhookId:button.dataset.testWebhook});toast('Message de test envoyé sur Discord.')}catch(error){toast('Test échoué : '+error.message,true)}finally{button.disabled=false}});list.querySelectorAll('[data-delete-webhook]').forEach(button=>button.onclick=async()=>{const config=webhookConfigs.find(item=>item.id===button.dataset.deleteWebhook);if(!config||!await siteDialog({title:`Supprimer « ${config.name} » ?`,message:'Cette destination et ses réglages d’événements seront supprimés.',confirmText:'Supprimer',danger:true}))return;button.disabled=true;try{await callWebhook('delete',{webhookId:config.id});webhookConfigs=webhookConfigs.filter(item=>item.id!==config.id);if(editingWebhookId===config.id)resetWebhookEditor();renderWebhookList();toast('Webhook supprimé.')}catch(error){toast('Suppression impossible : '+error.message,true);button.disabled=false}})}
  function updateWebhookAvatarPreview(){const preview=$('webhookAvatarPreview'),value=$('webhookAvatarUrl').value.trim();if(value){preview.src=value;preview.classList.remove('hidden')}else{preview.removeAttribute('src');preview.classList.add('hidden')}}
  function readExtraWebhookEmbeds(){return [1,2].map(index=>({title:$(`webhookEmbed${index}Title`).value.trim(),description:$(`webhookEmbed${index}Description`).value.trim(),image_url:$(`webhookEmbed${index}Image`).value.trim()})).filter(embed=>embed.title||embed.description||embed.image_url)}
  function fillExtraWebhookEmbeds(embeds=[]){[1,2].forEach((index)=>{const embed=embeds[index-1]||{};$(`webhookEmbed${index}Title`).value=embed.title||'';$(`webhookEmbed${index}Description`).value=embed.description||'';$(`webhookEmbed${index}Image`).value=embed.image_url||''})}
  $('webhookAvatarUrl').oninput=updateWebhookAvatarPreview;
  async function loadWebhookSettings(){if(currentProfile?.role!=='admin')return;try{const data=await callWebhook('get');webhookConfigs=data.webhooks||[];renderWebhookList();const target=$('webhookManualTarget'),selected=target.value;target.innerHTML='<option value="">Choisir un webhook…</option>'+webhookConfigs.map(config=>`<option value="${escapeHtml(config.id)}">${escapeHtml(config.name)}</option>`).join('');if(webhookConfigs.some(config=>config.id===selected))target.value=selected;$('webhookUrl').value=''}catch(error){$('webhookStatus').textContent='Indisponible';$('webhookList').innerHTML='<div class="empty">Impossible de charger les webhooks. Vérifie la session et le déploiement serveur.</div>';toast('Chargement des webhooks impossible : '+error.message,true)}}
  $('webhookForm').onsubmit=async event=>{event.preventDefault();if(currentProfile?.role!=='admin')return;const name=$('webhookName').value.trim(),usernameMode=$('webhookUsernameMode').value,avatarUrl=$('webhookAvatarUrl').value.trim(),mentionTarget=$('webhookMentionTarget').value.trim(),embedImageUrl=$('webhookEmbedImage').value.trim(),messageTemplate=$('webhookMessageTemplate').value.trim(),extraEmbeds=readExtraWebhookEmbeds(),webhookUrl=$('webhookUrl').value.trim(),events=Array.from(document.querySelectorAll('#webhookForm input[type=checkbox]:checked'),input=>input.value);if(!name)return toast('Donne un nom à ce webhook.',true);if(!editingWebhookId&&!webhookUrl)return toast('Colle une URL de webhook Discord.',true);try{await callWebhook('save',{webhookId:editingWebhookId||undefined,name,usernameMode,avatarUrl,mentionTarget,embedImageUrl,messageTemplate,extraEmbeds,webhookUrl,events});toast(editingWebhookId?'Webhook modifié.':'Webhook ajouté.');resetWebhookEditor();await loadWebhookSettings()}catch(error){toast('Enregistrement impossible : '+error.message,true)}};
  $('webhookCancelEdit').onclick=resetWebhookEditor;
  $('webhookManualSend').onclick=async()=>{const webhookId=$('webhookManualTarget').value,message=$('webhookManualMessage').value.trim();if(!webhookId)return toast('Choisis un webhook de destination.',true);if(!message)return toast('Écris un message avant de l’envoyer.',true);const button=$('webhookManualSend');button.disabled=true;try{await callWebhook('send',{webhookId,message});$('webhookManualMessage').value='';toast('Message envoyé sur Discord.')}catch(error){toast('Envoi impossible : '+error.message,true)}finally{button.disabled=false}};
  function setMessageTab(tab){const privateMode=tab==='private';document.querySelectorAll('[data-message-tab]').forEach(button=>button.classList.toggle('active',button.dataset.messageTab===(privateMode?'private':'general')));$('generalChatView').classList.toggle('hidden',privateMode);$('privateChatView').classList.toggle('hidden',!privateMode);if(privateMode){populateDirectMessageMembers();if($('directMessageMember').value)loadDirectMessages()}}
  function populateDirectMessageMembers(){const select=$('directMessageMember');if(!select)return;const selected=select.value;select.innerHTML='<option value="">Choisis un membre de l’équipe…</option>'+allProfiles.filter(profile=>profile.id!==currentUser?.id&&profile.status==='active').map(profile=>`<option value="${escapeHtml(profile.id)}">${escapeHtml(profile.nickname||profile.display_name)}</option>`).join('');if(allProfiles.some(profile=>profile.id===selected&&profile.status==='active'))select.value=selected;else select.value='';renderDirectContacts()}
  function renderDirectContacts(){const list=$('directContactsList');if(!list)return;const query=$('directContactSearch').value.trim().toLocaleLowerCase('fr'),selected=$('directMessageMember').value,people=allProfiles.filter(profile=>profile.id!==currentUser?.id&&profile.status==='active'&&(profile.nickname||profile.display_name).toLocaleLowerCase('fr').includes(query));$('directContactCount').textContent=String(allProfiles.filter(profile=>profile.id!==currentUser?.id&&profile.status==='active').length);list.innerHTML=people.map(profile=>{const name=profile.nickname||profile.display_name,unread=directUnreadCounts.get(profile.id)||0,initials=name.trim().split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase();return `<button type="button" class="direct-contact ${selected===profile.id?'active':''}" data-direct-contact="${escapeHtml(profile.id)}" aria-current="${selected===profile.id?'true':'false'}"><span class="direct-contact-avatar">${escapeHtml(initials)}</span><span class="direct-contact-copy"><strong>${escapeHtml(name)}</strong><small>${unread?'Nouveau message privé':'Conversation privée'}</small></span>${unread?`<span class="direct-contact-unread" aria-label="${unread} messages non lus">${unread>99?'99+':unread}</span>`:''}</button>`}).join('')||'<div class="empty direct-contact-empty">Aucun contact ne correspond à ta recherche.</div>';list.querySelectorAll('[data-direct-contact]').forEach(button=>button.onclick=()=>{const id=button.dataset.directContact;$('directMessageMember').value=id;renderDirectContacts();loadDirectMessages()})}
  function chatMessageMarkup(message,{direct=false,peerName='Membre'}={}){const mine=message.user_id===currentUser.id,sender=direct?(mine?'Moi':peerName):(allProfiles.find(item=>item.id===message.user_id)?.nickname||allProfiles.find(item=>item.id===message.user_id)?.display_name||(mine?currentProfile?.display_name:'Membre')),canDelete=currentProfile?.role==='admin';return `<article class="chat-message ${mine?'mine':''}"><div class="chat-message-meta"><strong>${escapeHtml(sender)}</strong><time datetime="${escapeHtml(message.created_at)}">${new Date(message.created_at).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'})}</time></div><p>${escapeHtml(message.body)}</p>${canDelete?`<div class="chat-message-actions"><button type="button" class="chat-message-delete" data-delete-chat-message="${escapeHtml(message.id)}" data-direct-message="${direct?'true':'false'}">Supprimer</button></div>`:''}</article>`}
  function bindChatDeleteButtons(container){container.querySelectorAll('[data-delete-chat-message]').forEach(button=>button.onclick=async()=>{if(!await siteDialog({title:'Supprimer ce message ?',message:'Cette suppression est définitive pour les membres qui y ont accès.',confirmText:'Supprimer',danger:true}))return;button.disabled=true;const table=button.dataset.directMessage==='true'?'team_direct_messages':'team_messages',{data,error}=await db.from(table).delete().eq('id',button.dataset.deleteChatMessage).select('id').maybeSingle();if(error){button.disabled=false;return toast('Suppression impossible : '+error.message,true)}if(!data){button.disabled=false;return toast('Le message est introuvable ou tu n’as pas les droits nécessaires.',true)}toast('Message supprimé.');if(table==='team_messages')loadMessages();else loadDirectMessages()})}
  async function loadMessages(){const pane=$('teamMessages');if(!pane||!currentUser)return;const wasAtBottom=pane.scrollHeight-pane.scrollTop-pane.clientHeight<90;const {data,error}=await db.from('team_messages').select('id,user_id,body,created_at').order('created_at',{ascending:false}).limit(100);if(error){pane.innerHTML='<div class="empty">Messagerie inaccessible. Vérifie que la migration SQL est appliquée et que ton compte est actif.</div>';return}const rows=(data||[]).reverse();pane.innerHTML=rows.map(message=>chatMessageMarkup(message)).join('')||'<div class="empty">Pas encore de message. Lance la discussion avec l’équipe.</div>';bindChatDeleteButtons(pane);if(wasAtBottom||rows.at(-1)?.user_id===currentUser.id)pane.scrollTop=pane.scrollHeight;await markDirectConversationRead(recipientId)}
  async function markDirectConversationRead(actorId){if(!actorId||!directUnreadCounts.get(actorId))return;const {error}=await db.from('team_notifications').update({read_at:new Date().toISOString()}).eq('kind','direct_message').eq('actor_id',actorId).is('read_at',null);if(!error)await refreshNotifications(false)}
  async function loadDirectMessages(){const pane=$('directMessages'),recipientId=$('directMessageMember')?.value;if(!pane||!currentUser)return;if(!recipientId){$('directChatTitle').textContent='Choisis une conversation';pane.innerHTML='<div class="empty">Choisis un contact à gauche pour ouvrir la conversation.</div>';return}const peer=allProfiles.find(profile=>profile.id===recipientId);if(!peer||peer.status!=='active'){pane.innerHTML='<div class="empty">Ce membre n’est plus actif. Choisis une autre personne.</div>';return}$('directChatTitle').textContent=peer.nickname||peer.display_name;const wasAtBottom=pane.scrollHeight-pane.scrollTop-pane.clientHeight<90;const [sent,received]=await Promise.all([db.from('team_direct_messages').select('id,sender_id,recipient_id,body,created_at').eq('sender_id',currentUser.id).eq('recipient_id',recipientId).order('created_at',{ascending:false}).limit(100),db.from('team_direct_messages').select('id,sender_id,recipient_id,body,created_at').eq('sender_id',recipientId).eq('recipient_id',currentUser.id).order('created_at',{ascending:false}).limit(100)]);if(sent.error||received.error){pane.innerHTML='<div class="empty">Messages privés indisponibles. Applique la migration team_direct_messages dans Supabase.</div>';return}const rows=[...(sent.data||[]),...(received.data||[])].sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)).slice(-100).map(row=>({...row,user_id:row.sender_id}));pane.innerHTML=rows.map(message=>chatMessageMarkup(message,{direct:true,peerName:peer.nickname||peer.display_name})).join('')||`<div class="empty">Aucun message avec ${escapeHtml(peer.nickname||peer.display_name)}. Commence la conversation.</div>`;bindChatDeleteButtons(pane);if(wasAtBottom||rows.at(-1)?.user_id===currentUser.id)pane.scrollTop=pane.scrollHeight}
  function connectTeamMessages(){if(!db)return;if(!teamMessageChannel)teamMessageChannel=db.channel('team-messages').on('postgres_changes',{event:'INSERT',schema:'public',table:'team_messages'},()=>{if(!$('messagesPage').classList.contains('hidden'))loadMessages()}).subscribe(status=>{$('chatConnectionState').textContent=status==='SUBSCRIBED'?'En direct':status==='CHANNEL_ERROR'?'Actualisation automatique':'Connexion…'});if(!directMessageChannel)directMessageChannel=db.channel('team-direct-messages').on('postgres_changes',{event:'INSERT',schema:'public',table:'team_direct_messages'},()=>{if(!$('messagesPage').classList.contains('hidden')&&!$('privateChatView').classList.contains('hidden')&&$('directMessageMember').value)loadDirectMessages()}).subscribe(status=>{$('directChatState').textContent=status==='SUBSCRIBED'?'Privé · En direct':status==='CHANNEL_ERROR'?'Privé · Actualisation auto':'Privé · Connexion…'});if(!teamMessagePoll)teamMessagePoll=setInterval(()=>{if(currentUser&&!$('messagesPage').classList.contains('hidden')){loadMessages();if(!$('privateChatView').classList.contains('hidden')&&$('directMessageMember').value)loadDirectMessages()}},12000)}
  function disconnectTeamMessages(){if(teamMessagePoll){clearInterval(teamMessagePoll);teamMessagePoll=null}if(teamMessageChannel&&db){db.removeChannel(teamMessageChannel);teamMessageChannel=null}if(directMessageChannel&&db){db.removeChannel(directMessageChannel);directMessageChannel=null}}
  $('messageForm').onsubmit=async event=>{event.preventDefault();const input=$('messageBody'),body=input.value.trim();if(!body)return toast('Écris un message avant de l’envoyer.',true);if(body.length>2000)return toast('Le message dépasse 2000 caractères.',true);const button=event.submitter;button.disabled=true;const {error}=await db.from('team_messages').insert({user_id:currentUser.id,body});button.disabled=false;if(error)return toast('Message non envoyé : '+error.message,true);input.value='';await loadMessages();input.focus()};
  $('directMessageForm').onsubmit=async event=>{event.preventDefault();const recipientId=$('directMessageMember').value,input=$('directMessageBody'),body=input.value.trim();if(!recipientId)return toast('Choisis le membre à qui écrire.',true);if(!body)return toast('Écris un message avant de l’envoyer.',true);if(body.length>2000)return toast('Le message dépasse 2000 caractères.',true);const button=event.submitter;button.disabled=true;const {error}=await db.from('team_direct_messages').insert({sender_id:currentUser.id,recipient_id:recipientId,body});button.disabled=false;if(error)return toast('Message privé non envoyé : '+error.message,true);input.value='';await loadDirectMessages();input.focus()};
  async function loadMyWarnings(){const panel=$("memberWarningsPanel");if(!panel)return;panel.classList.toggle("hidden",currentProfile?.role==="admin");if(currentProfile?.role==="admin")return;const {data,error}=await db.from("member_warnings").select("id,motif,description,reason,admin_name,created_at").eq("member_id",currentUser.id).order("created_at",{ascending:false});if(error){$("myWarnings").innerHTML='<div class="empty">Impossible de charger tes avertissements. L’administrateur doit appliquer la migration de <strong>supabase_setup.sql</strong> dans le SQL Editor Supabase.</div>';return}const warnings=data||[],disputesResult=await db.from("warning_disputes").select("warning_id,status").eq("user_id",currentUser.id),disputeMap=new Map((disputesResult.data||[]).map(item=>[item.warning_id,item.status]));$("myWarnings").innerHTML=warnings.map((w,index)=>warningCard(w,"Pour toi",w.admin_name||"Administration",false,index,disputeMap.get(w.id)||null)).join("")||'<div class="empty">Aucun avertissement ne t’a été attribué.</div>';document.querySelectorAll("[data-contest-warning]").forEach(button=>button.onclick=async()=>{const reason=await siteDialog({title:"Contester cet avertissement",message:"Explique calmement pourquoi tu contestes ce warn. Ta demande sera transmise à l’administration.",placeholder:"Ta contestation…",confirmText:"Envoyer la contestation",textarea:true});if(!reason?.trim())return;const {error}=await db.from("warning_disputes").insert({warning_id:button.dataset.contestWarning,user_id:currentUser.id,reason:reason.trim()});if(error)return toast("Contestation non envoyée : "+error.message,true);toast("Ta contestation a été envoyée à l’administration.");loadMyWarnings()})}
  async function loadAllDisputes(){const container=$("allDisputesList");if(!container||currentProfile?.role!=="admin")return;container.innerHTML='<div class="empty">Chargement des contestations…</div>';const [warnings,sanctions]=await Promise.all([db.from("warning_disputes").select("id,warning_id,user_id,reason,status,created_at").order("created_at",{ascending:false}).limit(100),db.from("sanction_disputes").select("id,sanction_id,member_id,reason,status,created_at,admin_note").order("created_at",{ascending:false}).limit(100)]);const rows=[];for(const row of warnings.data||[])rows.push({...row,kind:"warning",member:allProfiles.find(p=>p.id===row.user_id)?.nickname||allProfiles.find(p=>p.id===row.user_id)?.display_name||"Membre",title:"Avertissement contesté"});for(const row of sanctions.data||[])rows.push({...row,kind:"sanction",member:allProfiles.find(p=>p.id===row.member_id)?.nickname||allProfiles.find(p=>p.id===row.member_id)?.display_name||"Membre",title:"Suspension / bannissement contesté"});rows.sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));const open=rows.filter(row=>row.status==="open").length;$("teamDisputesCount").textContent=open?`· ${open}`:"";container.innerHTML=[...warnings.error?[`<div class="empty">Avertissements : ${escapeHtml(warnings.error.message)}</div>`]:[],...sanctions.error?[`<div class="empty">Sanctions : ${escapeHtml(sanctions.error.message)}. Applique la mise à jour SQL.</div>`]:[],...rows.map(row=>{const state=row.status==="open"?"En attente":row.status==="accepted"?"Acceptée":row.status==="dismissed"?"Refusée":"Examinée";const actions=row.status!=="open"?"":row.kind==="sanction"?`<div class="warning-actions"><button class="btn" data-resolve-dispute="accepted" data-dispute-kind="sanction" data-dispute-id="${row.id}" data-member-id="${row.member_id}">Accepter et rétablir l’accès</button><button class="btn danger" data-resolve-dispute="dismissed" data-dispute-kind="sanction" data-dispute-id="${row.id}">Refuser</button></div>`:`<div class="warning-actions"><button class="btn secondary" data-resolve-dispute="reviewed" data-dispute-kind="${row.kind}" data-dispute-id="${row.id}">Marquer examinée</button><button class="btn danger" data-resolve-dispute="dismissed" data-dispute-kind="${row.kind}" data-dispute-id="${row.id}">Classer</button></div>`;return `<article class="warning-card dispute-card"><div class="warning-card-head"><div><span class="dispute-type dispute-${row.kind}">${row.kind==="warning"?"WARN":"SANCTION"}</span><h3>${escapeHtml(row.title)}</h3><div class="warning-meta">De <strong>${escapeHtml(row.member)}</strong> · ${dateLabel(row.created_at)}</div></div><span class="pill">${state}</span></div><p class="dispute-summary">${escapeHtml(row.reason)}</p>${row.admin_note?`<p class="muted">Note admin : ${escapeHtml(row.admin_note)}</p>`:""}${actions}</article>`}).join("")].join("")||'<div class="empty">Aucune contestation pour le moment.</div>';container.querySelectorAll("[data-resolve-dispute]").forEach(button=>button.onclick=async()=>{const kind=button.dataset.disputeKind,status=button.dataset.resolveDispute;button.disabled=true;let error=null;if(kind==="sanction"&&status==="accepted"){const restored=await db.from("profiles").update({status:"active",suspended_until:null,restriction_reason:""}).eq("id",button.dataset.memberId);error=restored.error}if(!error&&kind==="sanction"){const result=await db.from("sanction_disputes").update({status,reviewed_by:currentUser.id,reviewed_at:new Date().toISOString()}).eq("id",button.dataset.disputeId);error=result.error}else if(!error){const table="warning_disputes",result=await db.from(table).update({status}).eq("id",button.dataset.disputeId);error=result.error}if(error){button.disabled=false;return toast("Impossible de traiter la contestation : "+error.message,true)}toast(status==="accepted"?"Contestation acceptée, accès rétabli.":status==="dismissed"?"Contestation classée.":"Contestation marquée examinée.");await refreshReports();loadAllDisputes()})}
  $("sendWarn").onclick=async()=>{const member_id=$("warnMember").value,motif=$("warnMotif").value,description=$("warnDescription").value.trim();if(!member_id||!description)return toast("Choisis un membre et décris les faits.",true);const {data:created,error}=await db.from("member_warnings").insert({member_id,admin_id:currentUser.id,admin_name:currentProfile.display_name||currentUser.email,motif,description,reason:description}).select("id").single();if(error)return toast(error.message,true);notifyWebhook("warning_created",created.id);$("warnDescription").value="";toast("Avertissement enregistré.");loadTeamWarnings()};
